import { Col } from "react-bootstrap";
import "./product-card.css";
import { useNavigate } from "react-router-dom";
import { toast } from "react-toastify";
import { useDispatch, useSelector } from "react-redux";
import { addToCart } from "../../app/features/cart/cartSlice";
import PopupDialog from "./../popupdialog";
import trackEvent from '../../utils/trackEvent';

import {selectedProduct} from "../../app/features/authSlice";
import { useState } from "react";

const ProductCard = ({ title, productItem }) => {
  const dispatch = useDispatch();
   const [isDialogOpen, setIsDialogOpen] = useState(false);
  const router = useNavigate();
  const handelClick = () => {
     localStorage.setItem("product", JSON.stringify(productItem))
    router(`/shop/${productItem.id}`);
  };
  const handelAdd = (productItem) => {
    dispatch(addToCart({ product: productItem, num: 1 }));
    toast.success("Product has been added to cart!");
  };

  const openDialog = () => {
    trackEvent("shared")
    setIsDialogOpen(true);
  };

  const closeDialog = () => {
    setIsDialogOpen(false);
  };

      // Star rating display component
      const StarRating = ({ rating, totalReviews }) => (
        <div className="average-rating">
          <div className="stars">
            {[1, 2, 3, 4, 5].map((star) => (
              <span
                key={star}
                className={`star ${star <= rating ? 'filled' : ''}`}
              >
                ★
              </span>
            ))}
          </div>
          {totalReviews > 0 && (
            <span className="rating-stats">
              {totalReviews} {totalReviews === 1 ? 'review' : 'reviews'}
            </span>
          )}
                    {totalReviews === 0 && (
            <span className="rating-stats">
              {totalReviews} {totalReviews === 1 ? 'review' : 'reviews'}
              </span>
          )}
        </div>
      );

  return (
    <Col md={3} sm={5} xs={10} className="product mtop">
      {title === "Big Discount" ? (
        <span className="discount">{productItem.discount}% Off</span>
      ) : null}
      <img
        loading="lazy"
        onClick={() => handelClick()}
        src={productItem.image_url}
        alt=""
      />
      <div className="product-details">
        <h3 onClick={() => handelClick()}>{productItem.name}</h3>
        <div className="rating-summary">
                  <StarRating 
                    rating={productItem.avg_rating} 
                    totalReviews={productItem.review_count}
                  />
                </div>

   
        <div className="price">
          <h4>${productItem.price}</h4>
          <button
            aria-label="Add"
            type="submit"
            className="add"
            onClick={() => handelAdd(productItem)}
          >
            <ion-icon name="add"></ion-icon>
          </button>
        </div>
      </div>
      <div class="social-buttons">

      <PopupDialog
        isOpen={isDialogOpen}
        onClose={closeDialog}
        title=""
        message="Ευχαριστούμε για το share"
      />
        <a  onClick={openDialog} target="_blank" className="fb">Facebook</a>
        <a   onClick={openDialog} target="_blank" className="insta">Instagram</a>
        <a  onClick={openDialog} target="_blank" className="x">X</a>
    </div>    
    </Col>
  );
};

export default ProductCard;
